updateItem:
export const updateItem = pikkuFunc({
  expose: true,
  description: 'Update an item. Admin only.',
  // "Admin only" was a sentence in a description, not a rule. The route carried
  // `auth: true`, which means signed in — so any shopper with an account could
  // edit the catalogue. `catalogue:write` was already declared in scopes.ts and
  // already granted to the admin role; nothing was checking it.
  scopes: ['catalogue:write'],
  input: UpdateItemInput,
  func: async ({ kysely }, { itemId, ...patch }) => {
    const updates: Record<string, unknown> = {
      updatedAt: new Date().toISOString(),
    };
    if (patch.name !== undefined) updates.name = patch.name;
    if (patch.description !== undefined)
      updates.description = patch.description;
    if (patch.priceCents !== undefined)
      updates.priceCents = patch.priceCents;
    if (patch.stock !== undefined) updates.stock = patch.stock;
    if (patch.imageUrl !== undefined)
      updates.imageUrl = patch.imageUrl;
    if (patch.isActive !== undefined)
      updates.isActive = patch.isActive ? 1 : 0;

    await kysely
      .updateTable('item')
      .set(updates)
      .where('itemId', '=', itemId)
      .execute();
  },
});

queueWorkerFunction:
export const sendOrderConfirmation = pikkuSessionlessFunc({
  expose: false,
  description:
    'Queue consumer: send order confirmation email after a successful payment.',
  input: SendOrderConfirmationInput,
  func: async ({ kysely, logger }, { orderId, userId }) => {
    const [order, user] = await Promise.all([
      kysely
        .selectFrom('order')
        .select(['orderId', 'totalCents', 'status', 'createdAt'])
        .where('orderId', '=', orderId)
        .executeTakeFirst(),
      kysely
        .selectFrom('user')
        .select(['email', 'name'])
        .where('id', '=', userId)
        .executeTakeFirst(),
    ]);

    if (!order || !user) {
      logger.warn(
        `sendOrderConfirmation: order or user not found (${orderId}, ${userId})`,
      );
      return;
    }

    // In production: call your email service here (SendGrid, Resend, etc.)
    logger.info({
      event: 'order_confirmation_sent',
      to: user.email,
      name: user.name,
      orderId: order.orderId,
      totalCents: order.totalCents,
    });
  },
});

