createOrder:
export const createOrder = pikkuFunc({
  expose: true,
  description:
    'Create an order from a basket and charge via the fake payment provider.',
  input: CreateOrderInput,
  output: CreateOrderOutput,
  func: async (
    { kysely, queueService, audit },
    { basketId, shippingAddress, cardToken },
    { session, rpc },
  ) => {
    const userId = session.userId;

    // Load basket items with current prices
    const basketItems = await kysely
      .selectFrom('basketItem')
      .innerJoin('item', 'item.itemId', 'basketItem.itemId')
      .select([
        'basketItem.itemId',
        'basketItem.quantity',
        'item.priceCents',
        'item.stock',
        'item.name',
      ])
      .where('basketItem.basketId', '=', basketId)
      .execute();

    if (basketItems.length === 0)
      throw new Error('Basket is empty');

    // Validate stock
    for (const bi of basketItems) {
      if (bi.quantity > bi.stock)
        throw new Error(`Insufficient stock for "${bi.name}"`);
    }

    const totalCents = basketItems.reduce(
      (sum, bi) => sum + bi.priceCents * bi.quantity,
      0,
    );
    const orderId = randomUUID();
    const now = new Date().toISOString();

    // Create order
    await kysely
      .insertInto('order')
      .values({
        orderId,
        userId,
        status: 'pending',
        totalCents,
        shippingAddress: JSON.stringify(shippingAddress),
        createdAt: now,
        updatedAt: now,
      })
      .execute();

    // Create order items
    await kysely
      .insertInto('orderItem')
      .values(
        basketItems.map((bi) => ({
          orderItemId: randomUUID(),
          orderId,
          itemId: bi.itemId,
          quantity: bi.quantity,
          unitPriceCents: bi.priceCents,
        })),
      )
      .execute();

    // Deduct stock
    for (const bi of basketItems) {
      await kysely
        .updateTable('item')
        .set({ stock: bi.stock - bi.quantity, updatedAt: now })
        .where('itemId', '=', bi.itemId)
        .execute();
    }

    // Process payment through Stripe, the same way the checkout workflow does.
    // Both used to call a fake service that succeeded unless the card token
    // ended in '0000', so neither path had ever met a payment provider.
    const paymentId = randomUUID();
    const paymentResult = await rpc.invoke('chargeCard', {
      orderId,
      totalCents,
      ...(cardToken ? { cardToken } : {}),
    });

    await kysely
      .insertInto('payment')
      .values({
        paymentId,
        orderId,
        amountCents: totalCents,
        provider: 'fake',
        status: paymentResult.status,
        providerRef:
          paymentResult.status === 'succeeded'
            ? paymentResult.providerRef
            : null,
        createdAt: now,
      })
      .execute();

    const orderStatus =
      paymentResult.status === 'succeeded'
        ? 'paid'
        : 'payment_failed';
    await kysely
      .updateTable('order')
      .set({ status: orderStatus, updatedAt: now })
      .where('orderId', '=', orderId)
      .execute();

    if (paymentResult.status === 'succeeded') {
      // Clear basket and enqueue confirmation email
      await kysely
        .deleteFrom('basketItem')
        .where('basketId', '=', basketId)
        .execute();
      await queueService.add('send-order-confirmation', {
        orderId,
        userId,
      });
      await audit?.audit({
        type: 'order.created',
        source: 'explicit',
        occurredAt: new Date().toISOString(),
        metadata: { orderId, userId },
      });
    }

    return { orderId, status: orderStatus, totalCents };
  },
});

scopedFunction:
// Administration is a scope, not a string comparison against a column. The old
// `session.role === 'admin'` shape could not be checked at build time, could
// not be granted through the console, and said nothing about *which* admin
// capability was needed.
//
// Defined here rather than beside its `wireHTTP` call: a file that both defines
// a function and wires it yields "metadata not found" from the inspector, and
// the wiring is skipped at startup. `DELETE /orders/:orderId` was wired,
// documented, and absent from the running server for exactly that reason.
export const deleteOrder = pikkuFunc({
  func: async ({ kysely }, { orderId }: { orderId: string }) => {
    await kysely
      .deleteFrom('order')
      .where('orderId', '=', orderId)
      .execute();
  },
  scopes: ['orders'],
});

funcThreeParams:
// Three parameters, always: services, data, wire.
//   services — your toolbox (db, logger, queues)
//   data     — the typed input, wherever it arrived from
//   wire     — the protocol context (session, http, channel, rpc)
export const getOrder = pikkuFunc({
  expose: true,
  description:
    'Get a single order. Users can only access their own orders.',
  input: GetOrderInput,
  output: GetOrderOutput,
  func: async ({ kysely }, { orderId }, { session }) => {
    const order = await kysely
      .selectFrom('order')
      .selectAll()
      .where('orderId', '=', orderId)
      .executeTakeFirst();

    if (!order) throw new Error('Order not found');
    if (
      order.userId !== session.userId &&
      session.role !== 'admin'
    ) {
      throw new Error('Forbidden');
    }

    const items = await kysely
      .selectFrom('orderItem')
      .innerJoin('item', 'item.itemId', 'orderItem.itemId')
      .select([
        'orderItem.itemId',
        'item.name',
        'orderItem.quantity',
        'orderItem.unitPriceCents',
      ])
      .where('orderItem.orderId', '=', orderId)
      .execute();

    return {
      orderId: order.orderId,
      status: order.status,
      totalCents: order.totalCents,
      // Nullable: a walk-through order placed before an address was captured
      // has none, and returning null beats throwing on a read.
      shippingAddress: order.shippingAddress
        ? JSON.parse(order.shippingAddress)
        : null,
      items: items.map((i) => ({
        ...i,
        lineTotalCents: i.unitPriceCents * i.quantity,
      })),
      createdAt: order.createdAt,
    };
  },
});

